// Busca en el comunicado de Superfinanciera la tasa de usura del mes en curso.
// PRIMERA EJECUCIÓN: correr a mano y revisar "evidencia"; si el formato de la página no coincide, ajustar aquí.
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const hoy = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const mesTxt = MESES[hoy.getMonth()], anio = String(hoy.getFullYear());
const html = String($input.first().json.data || $input.first().json.body || $input.first().json || '');
const texto = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&aacute;/g, 'á').replace(/&eacute;/g, 'é').replace(/&iacute;/g, 'í')
  .replace(/&oacute;/g, 'ó').replace(/&uacute;/g, 'ú').replace(/\s+/g, ' ');
const bajo = texto.toLowerCase();
// Ventanas de texto donde aparece "usura": se toman los porcentajes que trae cada una.
const candidatos = [];
let i = bajo.indexOf('usura');
while (i >= 0) {
  const ventana = texto.slice(Math.max(0, i - 400), i + 400);
  const vb = ventana.toLowerCase();
  const pcts = [...ventana.matchAll(/(\d{1,2}[.,]\d{1,2})\s?%/g)].map(x => parseFloat(x[1].replace(',', '.'))).filter(n => n > 10 && n < 80);
  if (pcts.length) candidatos.push({ delMes: vb.includes(mesTxt) && vb.includes(anio), pcts, ventana: ventana.slice(0, 400) });
  i = bajo.indexOf('usura', i + 5);
}
const elegido = candidatos.find(c => c.delMes) || null;
// La usura de consumo y ordinario es el porcentaje mayor de la ventana (el interés bancario corriente es menor).
const usura = elegido ? Math.max(...elegido.pcts) : null;
return [{ json: {
  encontrado: usura !== null, mesTexto: mesTxt + ' ' + anio, usuraEA: usura,
  evidencia: elegido ? elegido.ventana : (candidatos[0] ? candidatos[0].ventana : texto.slice(0, 400)),
  candidatos: candidatos.length
} }];

// No toca C2 (tope Plataform): el radicador lo calcula como usura - 0,05 y la hoja lo hace con su fórmula.
// Solo escribe si encontró la usura del mes y la hoja aún no está en este mes.
const e = $('Extraer usura del mes').first().json;
const v = ($('Sheets: leer SPREAD').first().json.values || []);
const actual = String((v[0] || [])[1] || '').trim().toLowerCase();
if (!e.encontrado) throw new Error('No se encontró la tasa de usura de ' + e.mesTexto + ' en Superfinanciera. Revisar a mano y actualizar B1/B2 de la hoja SPREAD. Evidencia: ' + e.evidencia);
const yaEsta = actual === e.mesTexto;
return [{ json: { escribir: !yaEsta, mesTexto: e.mesTexto, usuraEA: e.usuraEA,
  body: { valueInputOption: 'USER_ENTERED', data: [
    { range: "'Hoja 1'!B1", values: [[e.mesTexto]] },
    { range: "'Hoja 1'!B2", values: [[String(e.usuraEA) + '%']] }
  ] } } }];
